const action = $('Switch Action').itemMatching(0).json;
const candidates = items.map(i => ({
  id: i.json.id,
  task: i.json.task,
  lead: i.json.lead,
  status: i.json.status,
  latest_note: i.json.latest_note || i.json.note,
  next_step: i.json.next_step
}));
const userPrompt = `You decide whether a newly proposed WIP task already exists in the current open task list for the same project_client. If yes, output decision=match with the existing task id and a confidence 0..1. Otherwise output decision=new.\n\nPROJECT_CLIENT: ${action.project_client}\n\nNEW TASK PROPOSAL:\n${JSON.stringify({ task: action.task, lead: action.lead, status: action.status, latest_note: action.latest_note, next_step: action.next_step }, null, 2)}\n\nEXISTING OPEN TASKS FOR THIS PROJECT:\n${JSON.stringify(candidates, null, 2)}\n\nReturn strict JSON: { "decision": "match" | "new", "match_id": "<uuid or null>", "confidence": <0..1>, "reason": "<short>" }`;
return [{ json: { ...action, candidates, matcherUserPrompt: userPrompt } }];

const action = $('Build WIP Match Prompt').itemMatching(0).json;
const m = $json.output || {};
const threshold = Number($('Merge System Config').first().json.wipConfidenceThreshold ?? 0.82);
const matched = m.decision === 'match' && m.match_id && Number(m.confidence || 0) >= threshold;
return [{
  json: {
    ...action,
    matcher: m,
    action: matched ? 'update' : 'create',
    existing_task_id: matched ? m.match_id : action.existing_task_id,
    matcherMatched: matched
  }
}];

const source = $('Switch Action').itemMatching(0).json;
const out = $json || {};
const err = out.error ? [out.error.message || JSON.stringify(out.error)] : [];
const id = out.id || source.existing_task_id || out.wip_task_id || null;
return [{ json: { ...source, wip_task_id: id, action_applied: source.action, errors: [...(source.errors || []), ...err] } }];

const existingRows = $('Lookup Existing Meeting (Pre-Loop)').all().map(i => i.json || {});
const rowsByEvent = new Map();
for (const row of existingRows) {
  if (row.calendar_event_id && row.id && !rowsByEvent.has(row.calendar_event_id)) {
    rowsByEvent.set(row.calendar_event_id, row);
  }
}
return $('Clean Transcript').all().map(item => {
  const clean = item.json || {};
  return { json: { ...clean, existing_meeting_row: rowsByEvent.get(clean.calendar_event_id) || null } };
});

const meetings = $('Attach Meeting To Context').all().map(i => i.json);
const taskRows = items.map(i => i.json || {});
const targetDate = $('Resolve Date').first().json.targetDate;
return meetings.map(context => {
  const meetingId = context.meeting_id;
  const meeting = context.existing_meeting && context.existing_meeting.id ? context.existing_meeting : (meetingId ? { id: meetingId } : null);
  const existingTasksForThisMeeting = taskRows.filter(r => r && r.meeting_id === meetingId && r.wip_task_id);
  const createdToday = meeting && meeting.created_at ? String(meeting.created_at).slice(0,10) === targetDate : false;
  return { json: { ...context, existing_meeting: meeting, meeting_exists: !!meeting, doubleRunWarning: !!meeting && createdToday && existingTasksForThisMeeting.length > 0 } };
});

const out = [];
for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  const upstream = $('Rejoin Meetings By Event').itemMatching(i).json;
  const { existing_meeting_row, ...clean } = upstream;
  const existing_meeting = existing_meeting_row || row;
  const meeting_id = existing_meeting.id || row.id || clean.meeting_id || null;
  out.push({ json: { ...clean, meeting_id, existing_meeting } });
}
return out;

const action = $json;
const guard = $('Loop Per Meeting').first().json;
const meeting_id = guard.meeting_id;
return [{ json: { ...action, meeting_id, missing_meeting_id: !meeting_id, existing_meeting: guard.existing_meeting || null, meeting_exists: !!guard.meeting_exists, doubleRunWarning: !!guard.doubleRunWarning } }];

const base = $('Attach Meeting ID').itemMatching(0).json;
const shouldCascade = base.action_applied === 'complete' && !!base.wip_task_id;
return [{ json: { ...base, shouldCascade, close_wip_task_id: shouldCascade ? base.wip_task_id : null } }];

const applied = $('Normalize WIP Result').all().map(i => i.json);
let cascades = [];
try { cascades = $('Cascade Close Tickets').all().map(i => i.json); } catch (e) { cascades = []; }
const counts = { tasks_created: 0, tasks_updated: 0, tasks_completed: 0, tickets_auto_closed: 0, errors: [], doubleRunWarning: false };
for (const a of applied) {
  if (a.action_applied === 'create') counts.tasks_created += 1;
  if (a.action_applied === 'update') counts.tasks_updated += 1;
  if (a.action_applied === 'complete') counts.tasks_completed += 1;
  if (a.doubleRunWarning) counts.doubleRunWarning = true;
  if (Array.isArray(a.errors)) counts.errors.push(...a.errors);
}
counts.tickets_auto_closed = cascades.filter(c => c && !c.error).length;
for (const c of cascades) if (c && c.error) counts.errors.push(c.error.message || JSON.stringify(c.error));
const meeting = $('Loop Per Meeting').first().json;  // current iteration meeting context
return [{ json: { ...$('Resolve Date').first().json, ...counts, meeting_title: meeting.title || 'Meeting', meeting_id: meeting.meeting_id } }];
